import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, mul, float } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root group
  const root = new Group();

  // === Photo Plane ===
  const PLANE_WIDTH = 4.0;
  const PLANE_HEIGHT = 2.5;
  const geometry = new PlaneGeometry(PLANE_WIDTH, PLANE_HEIGHT, 64, 64);
  const material = new MeshStandardNodeMaterial();
  material.transparent = true;
  material.opacity = 0; // start invisible
  material.roughness = 0.6;
  material.metalness = 0.0;
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load textures (image & depth map)
  let imageTex, depthTex;
  ctx.textureLoader.loadTexture(config.imageUrl).then((t) => {
    imageTex = t;
    applyMaterialNodes();
  });
  ctx.textureLoader.loadTexture(config.depthMapUrl).then((t) => {
    depthTex = t;
    applyMaterialNodes();
  });

  function applyMaterialNodes() {
    if (!imageTex || !depthTex) return;
    const texNode = texture(imageTex);
    const dispNode = texture(depthTex);
    const displacementNode = mul(dispNode.r, float(0.18));
    material.colorNode = texNode;
    material.displacementNode = displacementNode;
    material.needsUpdate = true;
  }

  // === Caption Block ===
  const captionGroup = new Group();
  const PAD = 0.5; // 2x base unit (0.25)
  const startX = -PLANE_WIDTH / 2 + PAD;
  const startY = -PLANE_HEIGHT / 2 + PAD;
  // initial offset for rise‑in animation
  captionGroup.position.set(startX, startY + 0.4, 0.01);
  root.add(captionGroup);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const lineSpacing = 0.25;
  let cursorY = 0;

  const colors = config.visualSpec?.colors ?? {};
  const inkColor = colors.ink ?? '#16161d';
  const paperColor = colors.paper ?? '#e8ecf2';
  const accentColor = colors.accent ?? '#ff2a38';

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text ?? item.content ?? '', {
      fontSize: item.typography?.fontSize ?? 13,
      color: paperColor,
      align: 'left',
    });
    txt.position.set(0, -cursorY, 0);
    captionGroup.add(txt);
    cursorY += lineSpacing;

    // Insert accent hairline after headline
    if (item.role === 'headline') {
      const barGeom = new PlaneGeometry(0.75, 0.02);
      const barMat = new MeshStandardNodeMaterial({
        color: accentColor,
        emissive: accentColor,
        emissiveIntensity: 1.8,
        roughness: 0.5,
        metalness: 0.0,
        transparent: false,
      });
      const bar = new Mesh(barGeom, barMat);
      bar.position.set(0, -cursorY + 0.1, 0);
      captionGroup.add(bar);
    }
  }

  // === Cinematic Primitives ===
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const handle = fn(plane, prim.params);
        primitiveHandles.push(handle);
      }
    }
  }

  // === Animations ===
  const tl = gsap.timeline();
  tl.to(material, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    onUpdate: () => { material.needsUpdate = true; },
  });
  tl.to(
    captionGroup.position,
    {
      y: startY,
      duration: 0.7,
      ease: 'cubic-bezier(0.215,0.61,0.355,1)',
      delay: 0.12,
    },
    '<' // start after previous animation ends
  );

  // === Cleanup ===
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    tl.kill();
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    });
    geometry.dispose();
    material.dispose();
    if (imageTex) imageTex.dispose();
    if (depthTex) depthTex.dispose();
    // Dispose caption children resources
    captionGroup.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry && obj.geometry.dispose();
        obj.material && obj.material.dispose();
      }
    });
  };

  return root;
}
